import { Icon } from "@/registry/erbium/ui/icon";

import { Tabs, TabsList, TabsTrigger } from "@/registry/erbium/ui/tabs";

export const TabsIcons = () => (
  <Tabs defaultValue="preview">
    <TabsList>
      <TabsTrigger value="preview">
        <Icon name="app-window" />
        Preview
      </TabsTrigger>
      <TabsTrigger value="code">
        <Icon name="code" />
        Code
      </TabsTrigger>
    </TabsList>
  </Tabs>
);

import { TabsIcons } from "../examples/tabs-icons";

const Example = () => <TabsIcons />;

export default Example;
